use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
Schema::create('consumed_deliveries', function ($t) {
    $t->string('delivery_id')->primary();
});
$accept = function (array $message, string $signature, int $now) {
    $encoded = json_encode($message);
    if (! hash_equals(hash_hmac('sha256', $encoded, 'fixture-secret'), $signature)) {
        return 'invalid';
    }
    if (abs($now - $message['timestamp']) > 300) {
        return 'expired';
    }
    return DB::table('consumed_deliveries')->insertOrIgnore(['delivery_id' => $message['id']]) === 1
        ? 'accepted' : 'replay';
};
$message = ['id' => 'evt-1', 'timestamp' => 1000, 'body' => 'paid'];
$signature = hash_hmac('sha256', json_encode($message), 'fixture-secret');
echo $accept($message, $signature, 1010).':'.$accept($message, $signature, 1011).':'.$accept($message, $signature, 1400);
